/**
 * ZOYA GOODS logo — a genuine vector wordmark traced from the official
 * ZOYA GOODS artwork. One shared geometry for both colour variants; the
 * path is filled with `currentColor`, so the logo follows the text colour
 * of whatever container it sits in (Tailwind `text-*` utilities included).
 *
 * The variants only pick a sensible default colour — supply your own colour
 * via `className` (e.g. `text-porcelain`) to override.
 */
export interface ZoyaGoodsLogoProps {
  /** Colour default. Inline `text-*` colours in `className` win. */
  variant?: 'black' | 'white';
  /** Layout / sizing classes, e.g. `h-9 w-auto`. Keep `w-auto` for a proportional height. */
  className?: string;
  /** Fixed pixel height (width stays proportional). */
  height?: number;
  /** Fixed pixel width (height stays proportional). */
  width?: number;
  /** Accessible label. Set to `''` together with `aria-hidden` when decorative. */
  alt?: string;
  /** Wraps the logo in a homepage link. Omit when the logo already sits inside a link. */
  href?: string;
  'aria-hidden'?: boolean | 'true' | 'false';
  style?: React.CSSProperties;
}

