export function ZoyaGoodsLogo({
  variant = 'black',
  className,
  height,
  width,
  alt = 'ZOYA GOODS',
  href,
  'aria-hidden': ariaHidden,
  style,
}: ZoyaGoodsLogoProps) {
  const defaultColor = variant === 'white' ? 'text-white' : 'text-black';
  // Don't stack two text-colour utilities when the caller supplies its own.
  const useDefaultColor = !(className ?? '').match(/(?:^|\s)text-[^\s]+/);

  const svg = (
    <svg
      viewBox="0 0 1145 478"
      width={width}
      height={height}
      role="img"
      aria-label={alt}
      aria-hidden={ariaHidden === true || ariaHidden === 'true' ? true : undefined}
      focusable="false"
      style={style}
      className={cn('block h-8 w-auto', useDefaultColor && defaultColor, className)}
    >
      <path d={LOGO_GLYPH} fill="currentColor" />
    </svg>
  );

  if (href) {
    return (
      <Link href={href} className="inline-flex items-center">
        {svg}
      </Link>
    );
  }
  return svg;
}

export default ZoyaGoodsLogo;
